LB(a){return"\u0917\u094d\u0930\u093e\u0939\u0915 \u0906\u092a\u0915\u094b \u0911\u0930\u094d\u0921\u0930 \u201c"+a+"\u201d \u0938\u094c\u0902\u092a\u0928\u093e \u091a\u093e\u0939\u0924\u093e \u0939\u0948\u0964"},
gLC(){return"\u0915\u093e\u0930\u094d\u092f\u0938\u094d\u0925\u0932 \u0915\u0947 \u0932\u093f\u090f \u0928\u093f\u0915\u0932\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0910\u0938\u0947 \u0935\u0948\u0927 \u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u0938\u093e\u0925 \u0930\u0916\u0947\u0902 \u091c\u094b \u0926\u093f\u0916\u093e\u0924\u0947 \u0939\u094b\u0902 \u0915\u093f \u0906\u092a \u0915\u093e\u0928\u0942\u0928\u0940 \u0930\u0942\u092a \u0938\u0947 \u0915\u093e\u092e \u0915\u0930 \u0938\u0915\u0924\u0947 \u0939\u0948\u0902, \u091c\u093f\u0928\u092e\u0947\u0902 \u0906\u0935\u0936\u094d\u092f\u0915 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u092f\u093e \u092a\u0930\u092e\u093f\u091f \u0936\u093e\u092e\u093f\u0932 \u0939\u0948\u0902, \u0914\u0930 \u0917\u094d\u0930\u093e\u0939\u0915 \u0915\u0947 \u092e\u093e\u0901\u0917\u0928\u0947 \u092a\u0930 \u0909\u0928\u094d\u0939\u0947\u0902 \u0926\u093f\u0916\u093e\u090f\u0901\u0964 \u0915\u093e\u0930\u094d\u092f-\u0915\u094d\u0937\u0947\u0924\u094d\u0930, \u0915\u0940\u092e\u0924, \u092a\u0939\u0941\u0901\u091a \u0924\u0925\u093e \u0936\u0941\u0930\u0942 \u0939\u094b\u0928\u0947 \u0915\u0940 \u0924\u093e\u0930\u0940\u0916 \u0914\u0930 \u0938\u092e\u092f \u092d\u0940 \u092b\u093f\u0930 \u0924\u092f \u0915\u0930\u0947\u0902\u0964"},
