gL9(){return"\u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0915\u0940 \u092a\u094d\u0930\u0924\u0940\u0915\u094d\u0937\u093e"},
gLf(){return"\u0939\u0938\u094d\u0924\u093e\u0915\u094d\u0937\u0930\u093f\u0924"},
gLh(){return"\u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0935\u093e\u092a\u0938 \u0932\u093f\u092f\u093e \u0917\u092f\u093e"},
gLt(){return"\u092c\u093e\u0926 \u092e\u0947\u0902 \u0928\u093f\u0930\u094d\u0923\u092f \u0932\u0947\u0902"},
