gEZ(){return"\u0414\u043e\u0437\u0432\u043e\u043b\u0438\u0442\u0438 ClearFix \u043f\u043e\u0432\u2019\u044f\u0437\u0430\u0442\u0438 \u0432\u0445\u0456\u0434 \u0447\u0435\u0440\u0435\u0437 Apple \u0456\u0437 \u0446\u0438\u043c \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u043c \u0437\u0430\u043f\u0438\u0441\u043e\u043c \u0456 \u043d\u0430\u044f\u0432\u043d\u0438\u043c\u0438 \u0434\u0430\u043d\u0438\u043c\u0438 \u043f\u0440\u043e\u0444\u0456\u043b\u044e?"},
gF0(){return"Apple \u043f\u0456\u0434\u2019\u0454\u0434\u043d\u0430\u043d\u043e"},
gEX(){return"\u0426\u0435\u0439 \u0432\u0445\u0456\u0434 \u0447\u0435\u0440\u0435\u0437 Apple \u0443\u0436\u0435 \u0432\u0438\u043a\u043e\u0440\u0438\u0441\u0442\u043e\u0432\u0443\u0454\u0442\u044c\u0441\u044f \u0432 \u0456\u043d\u0448\u043e\u043c\u0443 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u043e\u043c\u0443 \u0437\u0430\u043f\u0438\u0441\u0456 ClearFix."},
gF_(){return"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u043f\u0456\u0434\u2019\u0454\u0434\u043d\u0430\u0442\u0438 Apple. \u0421\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437."},
gF3(){return"\u0412\u0430\u0448 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441 ClearFix \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043e. \u0412\u0438 \u043c\u043e\u0436\u0435\u0442\u0435 \u0432\u0438\u043b\u0443\u0447\u0438\u0442\u0438 ClearFix \u0437\u0456 \u0441\u043f\u0438\u0441\u043a\u0443 \xab\u0412\u0445\u0456\u0434 \u0437 Apple\xbb \u0443 \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u0430\u0445 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u043e\u0433\u043e \u0437\u0430\u043f\u0438\u0441\u0443 Apple."},
gF2(){return"\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u0456\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0456\u0457 Apple"},
gF8(){return"\u0417 \u043c\u0456\u0440\u043a\u0443\u0432\u0430\u043d\u044c \u0431\u0435\u0437\u043f\u0435\u043a\u0438 \u0443\u0432\u0456\u0439\u0434\u0456\u0442\u044c \u0432 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441 \u0437\u043d\u043e\u0432\u0443 \u0442\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u0456\u0442\u044c \u0441\u043f\u0440\u043e\u0431\u0443."},
gHO(){return"\u0412\u0438\u0434\u0430\u043b\u0456\u0442\u044c \u0447\u0435\u0440\u043d\u0435\u0442\u043a\u0438 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u044c, \u043f\u0435\u0440\u0448 \u043d\u0456\u0436 \u0432\u0438\u0434\u0430\u043b\u044f\u0442\u0438 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441."},
gHQ(){return"\u0421\u043a\u0430\u0441\u0443\u0439\u0442\u0435 \u043e\u043f\u0443\u0431\u043b\u0456\u043a\u043e\u0432\u0430\u043d\u0456 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f, \u043f\u0435\u0440\u0448 \u043d\u0456\u0436 \u0432\u0438\u0434\u0430\u043b\u044f\u0442\u0438 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441."},
gHP(){return"\u0417\u0430\u0432\u0435\u0440\u0448\u0456\u0442\u044c \u0430\u0431\u043e \u0440\u043e\u0437\u0456\u0440\u0432\u0456\u0442\u044c \u043f\u043e\u0442\u043e\u0447\u043d\u0456 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f, \u043f\u0435\u0440\u0448 \u043d\u0456\u0436 \u0432\u0438\u0434\u0430\u043b\u044f\u0442\u0438 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441."},
gHS(){return"\u041f\u043e\u043f\u0440\u043e\u0441\u0456\u0442\u044c \u0437\u0430\u043c\u043e\u0432\u043d\u0438\u043a\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0438 \u0430\u0431\u043e \u0440\u043e\u0437\u0456\u0440\u0432\u0430\u0442\u0438 \u0432\u0441\u0456 \u043f\u0440\u0438\u0437\u043d\u0430\u0447\u0435\u043d\u0456 \u0432\u0430\u043c \u0440\u043e\u0431\u043e\u0442\u0438, \u043f\u0435\u0440\u0448 \u043d\u0456\u0436 \u0432\u0438\u0434\u0430\u043b\u044f\u0442\u0438 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441."},
gHR(){return"\u0423\u0440\u0435\u0433\u0443\u043b\u044e\u0439\u0442\u0435 \u0432\u0441\u0456 \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u0456 \u0441\u043f\u043e\u0440\u0438, \u043f\u0435\u0440\u0448 \u043d\u0456\u0436 \u0432\u0438\u0434\u0430\u043b\u044f\u0442\u0438 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441."},
gHN(){return"\u041f\u043e\u0433\u0430\u0441\u0456\u0442\u044c \u0437\u0430\u0431\u043e\u0440\u0433\u043e\u0432\u0430\u043d\u0456\u0441\u0442\u044c, \u043f\u0435\u0440\u0448 \u043d\u0456\u0436 \u0432\u0438\u0434\u0430\u043b\u044f\u0442\u0438 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441."},
gHM(){return"\u041e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441 \u043d\u0435 \u043c\u043e\u0436\u043d\u0430 \u0432\u0438\u0434\u0430\u043b\u0438\u0442\u0438, \u0434\u043e\u043a\u0438 \u0454 \u0430\u043a\u0442\u0438\u0432\u043d\u0435 \u0437\u043e\u0431\u043e\u0432\u2019\u044f\u0437\u0430\u043d\u043d\u044f. \u0423\u0440\u0435\u0433\u0443\u043b\u044e\u0439\u0442\u0435 \u0439\u043e\u0433\u043e \u0442\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u0456\u0442\u044c \u0441\u043f\u0440\u043e\u0431\u0443."},
gCa(){return"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u0437\u0430\u0440\u0435\u0454\u0441\u0442\u0440\u0443\u0432\u0430\u0442\u0438\u0441\u044f. \u0421\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437."},
gId(){return"\u041e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441 \u0456\u0437 \u0446\u0456\u0454\u044e \u0430\u0434\u0440\u0435\u0441\u043e\u044e \u0435\u043b\u0435\u043a\u0442\u0440\u043e\u043d\u043d\u043e\u0457 \u043f\u043e\u0448\u0442\u0438 \u0432\u0436\u0435 \u0456\u0441\u043d\u0443\u0454. \u0423\u0432\u0456\u0439\u0434\u0456\u0442\u044c \u0430\u0431\u043e \u0432\u043a\u0430\u0436\u0456\u0442\u044c \u0456\u043d\u0448\u0443 \u0430\u0434\u0440\u0435\u0441\u0443."},
gJH(){return"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u0432\u0438\u0439\u0442\u0438 \u0437 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u043e\u0433\u043e \u0437\u0430\u043f\u0438\u0441\u0443. \u0421\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437."},
gVF(){return"\u041f\u0440\u043e\u0444\u0456\u043b\u044c \u0443\u0441\u043f\u0456\u0448\u043d\u043e \u043e\u043d\u043e\u0432\u043b\u0435\u043d\u043e"},
gVD(){return"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u043e\u043d\u043e\u0432\u0438\u0442\u0438 \u043f\u0440\u043e\u0444\u0456\u043b\u044c. \u0421\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437."},
gVE(){return"\u0417\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f \u043f\u0440\u043e\u0444\u0456\u043b\u044e \u0442\u0440\u0438\u0432\u0430\u0454 \u0437\u0430\u043d\u0430\u0434\u0442\u043e \u0434\u043e\u0432\u0433\u043e. \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0437'\u0454\u0434\u043d\u0430\u043d\u043d\u044f \u0442\u0430 \u0441\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437."},
gVy(){return"\u0412\u0438\u0439\u0442\u0438 \u0431\u0435\u0437 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f"},
gVx(){return"\u041f\u0440\u043e\u0434\u043e\u0432\u0436\u0438\u0442\u0438 \u0440\u0435\u0434\u0430\u0433\u0443\u0432\u0430\u043d\u043d\u044f"},
