gGd(){return"\u0426\u0435 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u0432\u0436\u0435 \u043c\u0430\u0454 \u0430\u043a\u0442\u0438\u0432\u043d\u0438\u0439 \u0434\u0456\u0430\u043b\u043e\u0433 \u0441\u043a\u0430\u0440\u0433\u0438."},
gGk(){return"\u0417\u0430\u0440\u0430\u0437 \u043d\u0430\u0434\u0456\u0441\u043b\u0430\u0442\u0438 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f \u0441\u043a\u0430\u0440\u0433\u0438 \u043d\u0435\u043c\u043e\u0436\u043b\u0438\u0432\u043e."},
gGF(){return"\u041f\u043e\u0442\u0440\u0456\u0431\u043d\u0430 \u0443\u0432\u0430\u0433\u0430: \u043d\u0430\u0434\u0456\u0439\u0448\u043b\u0430 \u0441\u043a\u0430\u0440\u0433\u0430"},
GA(a){return"\u0414\u043b\u044f \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \xab"+a+"\xbb \u043e\u043f\u0443\u0431\u043b\u0456\u043a\u043e\u0432\u0430\u043d\u043e \u043f\u0443\u0431\u043b\u0456\u0447\u043d\u0435 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f \u0441\u043a\u0430\u0440\u0433\u0438. \u0412\u0456\u0434\u043a\u0440\u0438\u0439\u0442\u0435 \u0434\u0456\u0430\u043b\u043e\u0433, \u0449\u043e\u0431 \u043e\u0437\u043d\u0430\u0439\u043e\u043c\u0438\u0442\u0438\u0441\u044f."},
gGE(){return"\u041d\u043e\u0432\u0435 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f \u0432 \u0434\u0456\u0430\u043b\u043e\u0437\u0456 \u0441\u043a\u0430\u0440\u0433\u0438"},
GD(a){return"\u0423 \u0434\u0456\u0430\u043b\u043e\u0437\u0456 \u0441\u043a\u0430\u0440\u0433\u0438 \u0449\u043e\u0434\u043e \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \xab"+a+"\xbb \u0437\u2019\u044f\u0432\u0438\u043b\u043e\u0441\u044f \u043d\u043e\u0432\u0435 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f. \u0412\u0456\u0434\u043a\u0440\u0438\u0439\u0442\u0435 \u0434\u0456\u0430\u043b\u043e\u0433, \u0449\u043e\u0431 \u043e\u0437\u043d\u0430\u0439\u043e\u043c\u0438\u0442\u0438\u0441\u044f \u0437 \u043d\u0438\u043c."},
gGB(){return"\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u0434\u0456\u0430\u043b\u043e\u0433 \u0441\u043a\u0430\u0440\u0433\u0438"},
gGC(){return"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u043f\u043e\u0437\u043d\u0430\u0447\u0438\u0442\u0438 \u0441\u043f\u043e\u0432\u0456\u0449\u0435\u043d\u043d\u044f \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043d\u0438\u043c - \u0432\u043e\u043d\u043e \u043c\u043e\u0436\u0435 \u0437\u2019\u044f\u0432\u0438\u0442\u0438\u0441\u044f \u0437\u043d\u043e\u0432\u0443."},
KJ(a){return"\u041d\u043e\u0432\u0435 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f \u0441\u043a\u0430\u0440\u0433\u0438 \u0434\u043b\u044f "+a},
gGl(){return"\u0421\u043a\u0430\u0440\u0433\u0430"},
gGG(){return"\u0421\u043a\u0430\u0440\u0433\u0430"},
gGI(){return"\u041f\u043e\u0442\u0440\u0456\u0431\u043d\u0430 \u0443\u0432\u0430\u0433\u0430: \u043d\u0430\u0434\u0456\u0439\u0448\u043b\u0430 \u0441\u043a\u0430\u0440\u0433\u0430"},
gGH(){return"\u041f\u0443\u0431\u043b\u0456\u0447\u043d\u0438\u0439 \u0434\u0456\u0430\u043b\u043e\u0433 \u0441\u043a\u0430\u0440\u0433\u0438 \u0431\u0430\u0447\u0430\u0442\u044c \u0443\u0441\u0456, \u0434\u043e\u043a\u0438 \u0441\u0442\u043e\u0440\u043e\u043d\u0430, \u044f\u043a\u0430 \u0439\u043e\u0433\u043e \u0432\u0456\u0434\u043a\u0440\u0438\u043b\u0430, \u043d\u0435 \u043f\u043e\u0437\u043d\u0430\u0447\u0438\u0442\u044c \u043a\u043e\u043d\u0444\u043b\u0456\u043a\u0442 \u044f\u043a \u0443\u0440\u0435\u0433\u0443\u043b\u044c\u043e\u0432\u0430\u043d\u0438\u0439."},
