gVJ(){return"\u0414\u043e\u0434\u0430\u0442\u0438 \u0440\u0456\u0434\u043d\u0443 \u043c\u043e\u0432\u0443"},
gVH(){return"\u0414\u043e\u0434\u0430\u0442\u0438 \u0456\u043d\u043e\u0437\u0435\u043c\u043d\u0443 \u043c\u043e\u0432\u0443"},
gWl(){return"\u0412\u0432\u0435\u0434\u0456\u0442\u044c \u0449\u043e\u043d\u0430\u0439\u043c\u0435\u043d\u0448\u0435 \u0434\u0432\u0430 \u0441\u0438\u043c\u0432\u043e\u043b\u0438 \u043d\u0430\u0437\u0432\u0438 \u0430\u0431\u043e \u043a\u043e\u0434\u0443 \u043c\u043e\u0432\u0438, \u043a\u0440\u0456\u043c \u043f\u0440\u043e\u0431\u0456\u043b\u0456\u0432, \u0449\u043e\u0431 \u043f\u043e\u0431\u0430\u0447\u0438\u0442\u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0438."},
X0(a,b){return"\u0420\u0430\u0439\u043e\u043d: "+a+" ("+b+" \u043a\u043c)"},
X1(a,b){return a+" \u0456 \u043d\u0430\u0439\u0431\u043b\u0438\u0436\u0447\u0456 \u0440\u0430\u0439\u043e\u043d\u0438 ("+b+" \u043a\u043c)"},
X3(a,b){return a+" \u0442\u0430 \u043e\u043a\u043e\u043b\u0438\u0446\u0456 ("+b+" \u043a\u043c)"},
X2(a,b){return a+" \u0456 \u0441\u0443\u0441\u0456\u0434\u043d\u0456 \u043d\u0430\u0441\u0435\u043b\u0435\u043d\u0456 \u043f\u0443\u043d\u043a\u0442\u0438 ("+b+" \u043a\u043c)"},
gC0(){return"\u0424\u0430\u043a\u0442\u0438\u0447\u043d\u0430 \u043e\u043f\u043b\u0430\u0442\u0430"},
gBM(){return"\u041f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u044c\u0442\u0435 \u0437\u0430\u0433\u0430\u043b\u044c\u043d\u0443 \u0441\u0443\u043c\u0443, \u0441\u043f\u043b\u0430\u0447\u0435\u043d\u0443 \u0437\u0430 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f."},
gBK(){return"\u0423\u0441\u044c\u043e\u0433\u043e \u0441\u043f\u043b\u0430\u0447\u0435\u043d\u043e \u0432\u0438\u043a\u043e\u043d\u0430\u0432\u0446\u044e, CAD"},
gBS(){return"\u0423\u0441\u044c\u043e\u0433\u043e \u043e\u0442\u0440\u0438\u043c\u0430\u043d\u043e, CAD"},
gBL(){return"\u0417\u0430 \u0432\u0441\u0435 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f, \u0432\u043a\u043b\u044e\u0447\u043d\u043e \u0437 \u0430\u0432\u0430\u043d\u0441\u0430\u043c\u0438 \u0439 \u043e\u043a\u0440\u0435\u043c\u0438\u043c\u0438 \u043f\u0435\u0440\u0435\u043a\u0430\u0437\u0430\u043c\u0438, \u0437\u0430 \u0432\u0438\u0440\u0430\u0445\u0443\u0432\u0430\u043d\u043d\u044f\u043c \u043e\u0442\u0440\u0438\u043c\u0430\u043d\u0438\u0445 \u043f\u043e\u0432\u0435\u0440\u043d\u0435\u043d\u044c. \u041f\u0440\u044f\u043c\u0456 \u043f\u043e\u043a\u0443\u043f\u043a\u0438 \u0432 \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0456 \u043d\u0435 \u0432\u0440\u0430\u0445\u043e\u0432\u0443\u044e\u0442\u044c\u0441\u044f."},
gBu(){return"\u0421\u0443\u043c\u0430 \u0437\u0430\u043c\u043e\u0432\u043d\u0438\u043a\u0430"},
gBQ(){return"\u0421\u0443\u043c\u0430 \u0432\u0438\u043a\u043e\u043d\u0430\u0432\u0446\u044f"},
gBl(){return"\u0423\u0437\u0433\u043e\u0434\u0436\u0435\u043d\u0430 \u0441\u0443\u043c\u0430"},
gBm(){return"\u0421\u0443\u043c\u0430 \u0432\u0456\u0434\u0440\u0456\u0437\u043d\u044f\u0454\u0442\u044c\u0441\u044f"},
gBX(){return"\u0423\u0441\u0456 \u043e\u043f\u043b\u0430\u0442\u0438 \u0442\u0430 \u043f\u043e\u0432\u0435\u0440\u043d\u0435\u043d\u043d\u044f \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0456"},
gBE(){return"\u041e\u043f\u043b\u0430\u0442\u0430 \u0432\u043a\u043b\u044e\u0447\u0430\u0454 \u043c\u0430\u0442\u0435\u0440\u0456\u0430\u043b\u0438"},
gBF(){return"\u041e\u043f\u043b\u0430\u0442\u0430 \u0432\u043a\u043b\u044e\u0447\u0430\u0454 \u043f\u043e\u0434\u0430\u0442\u043e\u043a \u0456\u0437 \u043f\u0440\u043e\u0434\u0430\u0436\u0443"},
gBG(){return"\u041c\u0430\u0442\u0435\u0440\u0456\u0430\u043b\u0438"},
gBZ(){return"\u041f\u043e\u0434\u0430\u0442\u043e\u043a"},
gBH(){return"\u041f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0436\u0435\u043d\u0430 \u0441\u043e\u0431\u0456\u0432\u0430\u0440\u0442\u0456\u0441\u0442\u044c \u0432\u0430\u0448\u0438\u0445 \u043c\u0430\u0442\u0435\u0440\u0456\u0430\u043b\u0456\u0432 \u0434\u043b\u044f \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u0431\u0435\u0437 \u0432\u0456\u0434\u0448\u043a\u043e\u0434\u043e\u0432\u0443\u0432\u0430\u043d\u043e\u0433\u043e \u043f\u043e\u0434\u0430\u0442\u043a\u0443 \u0437\u0430\u043a\u0443\u043f\u0456\u0432\u043b\u0456. \u041d\u0435 \u0432\u043a\u043b\u044e\u0447\u0430\u0439\u0442\u0435 \u043f\u043e\u043a\u0443\u043f\u043a\u0438 \u0437\u0430\u043c\u043e\u0432\u043d\u0438\u043a\u0430, \u043f\u043e\u0432\u0435\u0440\u043d\u0435\u043d\u0456 \u0442\u043e\u0432\u0430\u0440\u0438, \u043e\u0441\u043e\u0431\u0438\u0441\u0442\u0456 \u0432\u0438\u0442\u0440\u0430\u0442\u0438 \u0439 \u0431\u0430\u0433\u0430\u0442\u043e\u0440\u0430\u0437\u043e\u0432\u0456 \u0456\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442\u0438. \u041d\u0430\u0446\u0456\u043d\u043a\u0430 \u0437\u0430\u043b\u0438\u0448\u0430\u0454\u0442\u044c\u0441\u044f \u0432 \u0431\u0430\u0437\u0456 \u043a\u043e\u043c\u0456\u0441\u0456\u0457."},
